parameters.jsCode:
const rowData = $input.item.json.rowData;

const clean = arr => [...new Set(
  arr.map(e => String(e || '').trim().toLowerCase()).filter(e => e.includes('@'))
)];

// TO: el requester (KAM solicitante)
const recipients = clean([ rowData['Requester mail'] ]).join(',');

// Nombre legible para el adjunto
const bin = { ...$input.item.binary };
if (bin.invoicePdf) {
  bin.invoicePdf = {
    ...bin.invoicePdf,
    fileName: 'Factura_' + String($input.item.json.invoiceNumber || 'Huspy').replace(/[\\/:*?"<>|]/g, '-') + '.pdf',
    fileExtension: 'pdf',
    mimeType: 'application/pdf'
  };
}

const checkoutLink = String($input.item.json.checkoutLink || rowData['Checkout link'] || '').trim();

return {
  json: { ...($input.item.json), recipients: recipients, checkoutLink: checkoutLink },
  binary: bin
};

options.ccList:
={{ [...new Set(
  [
    $json.rowData['Agent supply email'],
    $json.rowData['Agent sales email'],
    ...String((
      $('Read Mapeo Ciudades').all().find(m =>
        String(m.json.City).trim().toLowerCase() ===
        String($json.rowData['City'] || '').trim().toLowerCase()
      )?.json['KAM email']
    ) || '').split(',')
  ]
  .map(e => String(e || '').trim().toLowerCase())
  .filter(e => e.includes('@'))
  .filter(e => e !== String($json.recipients || '').trim().toLowerCase())
)].join(',') }}

