={{ (() => {
  const row = $('Loop Each Row').item.json;   // fila del GS
  const inv = $json;                          // datos de la factura Xero (invoiceNumber, invoiceId, amountDue)
  const cfg = $('Checkout Defaults').first().json;

  const pick = (rowVal, fallback) => { const v = String(rowVal ?? '').trim(); return v === '' ? fallback : v; };
  const bool = (rowVal, fallback) => { const v = String(rowVal ?? '').trim().toLowerCase();
    if (v === '') return fallback; return ['true','si','sí','yes','1','x'].includes(v); };

  const days = Number(pick(row['Checkout expiry days'], cfg.expiryDays));
  const methods = pick(row['Checkout methods'], cfg.paymentMethods).split(',').map(s => s.trim()).filter(Boolean);

  // Descripción visible en la página de pago (máx. 100 caracteres en Checkout)
  const desc = (String(inv.invoiceNumber || '') + ' · ' + String(row['Invoice description'] || '')).slice(0, 100);
  const email = String(row['Customer email'] || '').trim();

  const body = {
    amount: Math.round(Number(inv.amountDue) * 100),
    currency: pick(row['Checkout currency'], cfg.currency),
    billing: { address: { country: pick(row['Checkout country'], cfg.country) } },
    processing_channel_id: pick(row['Checkout channel'], cfg.processingChannelId),
    reference: String(inv.invoiceNumber || row.importKey),
    description: desc,
    products: [{ name: desc, quantity: 1, price: Math.round(Number(inv.amountDue) * 100) }],
    metadata: { importKey: row.importKey, invoiceNumber: inv.invoiceNumber, invoiceId: inv.invoiceId,
                jiraTicket: String(row['Jira Ticket'] || ''), contactName: row['*ContactName'] },
    expires_in: days * 86400,
    locale: pick(row['Checkout locale'], cfg.locale),
    allow_payment_methods: methods,
    '3ds': { enabled: bool(row['Checkout 3DS'], cfg.threeDs), attempt_n3d: true },
    capture: bool(row['Checkout capture'], cfg.capture),
    customer: Object.assign({ name: row['*ContactName'] }, email ? { email } : {}),
    payment_method_configuration: { card: { store_payment_details: 'disabled' } }
  };
  const ret = pick(row['Checkout return url'], cfg.returnUrl);
  if (ret) body.return_url = ret;
  return JSON.stringify(body);
})() }}
